/// <summary>
/// A get/set method to idenitfy the report name.
/// </summary>
/// <param name = "_metcashReportName">SSRS report name</param>
/// <returns>Returns the SSRS report name</returns>
[ DataMemberAttribute('MetcashReportName'), SysOperationControlVisibilityAttribute(false)]
public SRSCatalogItemName parmMetcashReportName(SRSCatalogItemName _metcashReportName = metcashReportName)
{
    metcashReportName = _metcashReportName;
    return metcashReportName;
}
